test('P6 interaction targets and preview are local controls with protected instance edits',async()=>{const {startInterfacePrototype}=await import('../../lib/interface/prototype');const {InterfacePrototypePlayer}=await import('./InterfacePrototype');interfaceSession.start();interfaceSession.transact(d=>{addNode(d,d.pages[0].id,'frame');addNode(d,d.pages[0].id,'frame');});interfaceSession.select(interfaceSession.get().document!.nodes[0].id);const properties=renderToStaticMarkup(<InterfaceProperties/>);assert.ok(properties.includes('Click to frame'));assert.ok(properties.includes('Hover to frame'));assert.ok(properties.includes('Set flow start'));const player=renderToStaticMarkup(<InterfacePrototypePlayer initial={startInterfacePrototype(interfaceSession.get().document!)} onClose={()=>{}}/>);assert.ok(player.includes('role="dialog"'));assert.ok(player.includes('Close preview'));assert.ok(player.includes('No URLs, scripts'));interfaceSession.clear();});
test('P7 frame mode, variant property controls and snapping settings use existing panels',async()=>{const {createComponent,addComponentVariant}=await import('../../lib/interface/components');const {addVariantProperty}=await import('../../lib/interface/variantProperties');interfaceSession.start();interfaceSession.transact(d=>{const root=addNode(d,d.pages[0].id,'frame'),c=createComponent(d,root,'Card');addComponentVariant(d,c,d.components![0].variants[0].id,'Alternate');addVariantProperty(d,c,'State');});interfaceSession.select(interfaceSession.get().document!.nodes[0].id);const html=renderToStaticMarkup(<InterfaceProperties/>);assert.ok(html.includes('Frame variable mode'));assert.ok(html.includes('Variant properties'));assert.ok(html.includes('Smart sibling guides'));assert.ok(html.includes('Canvas rulers'));assert.ok(html.includes('Value 2'));interfaceSession.clear();});
test('P8 experimental library and overlay choices are explicit local controls',()=>{interfaceSession.start();interfaceSession.transact(d=>{const root=addNode(d,d.pages[0].id,'frame');d.components=[];});const left=renderToStaticMarkup(<InterfaceLayers/>);assert.ok(left.includes('Local component library'));assert.ok(left.includes('not the native project container'));interfaceSession.select(interfaceSession.get().document!.nodes[0].id);const right=renderToStaticMarkup(<InterfaceProperties/>);assert.ok(right.includes('Overlay'));assert.ok(right.includes('Click to frame / Action'));interfaceSession.clear();});
test('P9 tree has one roving stop and expanded semantic hierarchy; canvas names and resize help remain accessible',()=>{interfaceSession.start();interfaceSession.transact(d=>{const f=addNode(d,d.pages[0].id,'frame');addNode(d,d.pages[0].id,'text',f);});interfaceSession.select(interfaceSession.get().document!.nodes[0].id);const left=renderToStaticMarkup(<InterfaceLayers/>),canvas=renderToStaticMarkup(<InterfaceCanvas/>),right=renderToStaticMarkup(<InterfaceProperties/>);assert.ok(left.includes('role="tree"'));const tree=left.slice(left.indexOf('<ul role="tree"'));assert.equal((tree.match(/tabindex="0"/g)??[]).length,1);assert.equal((left.match(/role="treeitem"/g)??[]).length,2);assert.ok(left.includes('aria-level="2"'));assert.ok(left.includes('aria-expanded="true"'));assert.ok(canvas.includes('interface-keyboard-help'));assert.ok(canvas.includes('Alt + arrows resize'));assert.ok(canvas.includes('role="group" aria-label="Frame · Frame"'));assert.ok(right.includes('PNG @3x'));interfaceSession.clear();});
test('P10 page controls and generic preset warning render in existing layers panel',()=>{interfaceSession.start();const html=renderToStaticMarkup(<InterfaceLayers/>);assert.ok(html.includes('Duplicate page'));assert.ok(html.includes('Page earlier'));assert.ok(html.includes('Page later'));assert.ok(html.includes('Frame presets'));assert.ok(html.includes('390 × 844'));assert.ok(html.includes('not hardware specifications'));interfaceSession.clear();});

test('P11 instance swap select and property rename/remove controls render',async()=>{const {createComponent,instantiateComponent}=await import('../../lib/interface/components');const {addVariantProperty}=await import('../../lib/interface/variantProperties');interfaceSession.start();let card='',instance='';interfaceSession.transact(d=>{const a=addNode(d,d.pages[0].id,'frame');card=createComponent(d,a,'Card');addVariantProperty(d,card,'State');const b=addNode(d,d.pages[0].id,'frame');createComponent(d,b,'Button');instance=instantiateComponent(d,card,d.components![0].variants[0].id,d.pages[0].id);});interfaceSession.select(instance);const html=renderToStaticMarkup(<InterfaceProperties/>);assert.ok(html.includes('aria-label="Component"'));assert.ok(html.includes('>Card</option>'));assert.ok(html.includes('>Button</option>'));assert.ok(html.includes('Matching layers keep their overrides'));interfaceSession.select(interfaceSession.get().document!.nodes.find(n=>n.kind==='frame')!.id);const master=renderToStaticMarkup(<InterfaceProperties/>);assert.ok(master.includes('Rename property'));assert.ok(master.includes('Remove property'));interfaceSession.clear();});

test('P12 typed property and timed transition controls render',async()=>{const {createComponent,instantiateComponent}=await import('../../lib/interface/components');const {addTypedProperty}=await import('../../lib/interface/variantProperties');interfaceSession.start();let card='',instance='';interfaceSession.transact(d=>{const a=addNode(d,d.pages[0].id,'frame');const text=addNode(d,d.pages[0].id,'text',a);card=createComponent(d,a,'Card');addTypedProperty(d,card,'Label','text',d.nodes.find(n=>n.id===text)!.componentSlot!);instance=instantiateComponent(d,card,d.components![0].variants[0].id,d.pages[0].id);d.nodes.find(n=>n.id===a)!.prototypeLinks=[{trigger:'afterDelay',targetFrameId:d.nodes.find(n=>n.id===a)!.id,delayMs:300,transition:{kind:'dissolve',durationMs:250}}];});interfaceSession.select(interfaceSession.get().document!.nodes.find(n=>n.id===card&&false)?'':instance);const html=renderToStaticMarkup(<InterfaceProperties/>);assert.ok(html.includes('Label'));interfaceSession.select(interfaceSession.get().document!.nodes.find(n=>n.kind==='frame')!.id);const master=renderToStaticMarkup(<InterfaceProperties/>);assert.ok(master.includes('Property type'));assert.ok(master.includes('Target layer')===false);assert.ok(master.includes('After delay (ms) to frame'));assert.ok(master.includes('Transition'));assert.ok(master.includes('Dissolve'));assert.ok(master.includes('smart-animate matches layers by name'));interfaceSession.clear();});
